```cpp
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

class SecureString {
private:
    std::string data;

public:
    SecureString(const std::string& str) : data(str) {
        // Remove any non-alphanumeric characters
        data.erase(std::remove_if(data.begin(), data.end(),
                                   [](char c) { return !std::isalnum(c); }),
                   data.end());
    }

    SecureString& operator=(const SecureString& other) {
        if (this != &other) {
            data = other.data;
        }
        return *this;
    }

    std::string toString() const {
        return data;
    }
};

int main() {
    SecureString str1("Hello, World!");
    SecureString str2 = str1; // Copy constructor
    str2 = str1; // Copy assignment operator

    std::cout << "str1: " << str1.toString() << std::endl;
    std::cout << "str2: " << str2.toString() << std::endl;

    return 0;
}
```

