    if (!fs::exists(uploadPath) || !fs::is_directory(uploadPath))
    {
        throw std::runtime_error("Upload path does not exist or is not a directory.");
    }

    // Ensure the normalized path is within the upload directory
    if (!fs::exists(normalizedPath) || !fs::is_directory(normalizedPath))
    {
        throw std::runtime_error("File path does not exist or is not a directory.");
    }

    // Create the necessary directories if they do not exist
    if (!fs::exists(normalizedPath.parent_path()))
    {
        fs::create_directories(normalizedPath.parent_path());
    }

    return saveTo(normalizedPath);
}
