    struct usb_device *dev;
    struct usb_interface *intf;
    struct usb_endpoint_descriptor *tx_endpoint;
    struct usb_endpoint_descriptor *rx_endpoint;
    int block_size;
};

static int rsi_init_usb_interface(struct rsi_91x_usbdev *rsi_dev,
				  struct usb_interface *pfunction)
{
    int status;

    rsi_dev->dev = pfunction->dev;
    rsi_dev->intf = pfunction;
    rsi_dev->tx_endpoint = pfunction->dev->dev->cur_altsetting->endpoint;
    rsi_dev->rx_endpoint = pfunction->dev->dev->cur_altsetting->endpoint;
    rsi_dev->block_size = pfunction->max_packet_size;

    if (rsi_dev->tx_endpoint == NULL || rsi_dev->rx_endpoint == NULL) {
        pr_err("Invalid USB endpoints\n");
        return -EINVAL;
    }

    return 0;
}
```

