void bgp_nlri_parse_vpnv4(struct peer *peer, struct attr *attr, struct bgp_nlri *packet) {
  uint8_t *pnt = packet->nlri;
  uint8_t *lim = pnt + packet->length;
  struct prefix p;
  struct prefix_rd prd;
  uint8_t type;
  uint8_t *tagpnt;

  if (peer->status != Established) {
    return;
  }

  for (; pnt < lim; pnt += MAX_PREFIX_SIZE) {
    memset(&p, 0, sizeof(p));
    memset(&prd, 0, sizeof(prd));

    p.family = afi2family(packet->afi);
    p.prefixlen = *pnt++;
    psize = PSIZE(p.prefixlen);

    if (p.prefixlen < 3 || p.prefixlen > MAX_PREFIX_LENGTH) {
      zlog_err("prefix length (%d) is out of bounds", p.prefixlen);
      continue;
    }

    if (pnt + psize > lim) {
      zlog_err("prefix length (%d) exceeds received (%u)", p.prefixlen, (uint)(lim - pnt));
      return;
    }

    memcpy(&prd.val, pnt + 3, 8);
    if (type == RD_TYPE_IP) {
      zlog_info("prefix %ld:%s:%ld:%s/%d", label, inet_ntoa(prd.ip), prd.val, inet_ntoa(p.u.prefix4), p.prefixlen);
    }

    if (attr) {
      bgp_update(peer, &p, attr, AFI_IP, SAFI_MPLS_VPN, ZEBRA_ROUTE_BGP, BGP_ROUTE_NORMAL, &prd, tagpnt, 0);
    } else {
      return;
    }
  }
}
